apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "app.fullname" . }}
  labels:
    {{- include "app.labels" . | nindent 4 }}
spec:
  {{- if not .Values.autoscaling.enabled }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "app.selectorLabels" . | nindent 6 }}
  {{- with .Values.deploymentStrategy }}
  strategy:
    {{- toYaml . | trim | nindent 4 }}
  {{- end }}
  template:
    metadata:
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "app.selectorLabels" . | nindent 8 }}
        {{- with .Values.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      {{- with .Values.hostAliases }}
      hostAliases:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "app.serviceAccountName" . }}
      securityContext:
        {{- toYaml .Values.podSecurityContext | nindent 8 }}
      volumes:
        - name: data
            {{- if .Values.persistence.enabled }}
          persistentVolumeClaim:
            claimName: {{ .Values.persistence.existingClaim | default (include "app.fullname" .) }}
            {{- else }}
          emptyDir: { }
            {{- end }}
      containers:
        - name: {{ .Chart.Name }}
          securityContext:
            privileged: true
            {{- with .Values.securityContext }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
          image: "{{ .Values.image.repository }}:{{ default .Chart.AppVersion .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          ports:
            - name: http
              containerPort: {{ .Values.service.port }}
              protocol: TCP
          livenessProbe:
            initialDelaySeconds: {{ .Values.app.livenessProbe.initialDelaySeconds | default 60 }}
            periodSeconds: {{ .Values.app.livenessProbe.periodSeconds | default 5 }}
            timeoutSeconds: {{ .Values.app.livenessProbe.timeoutSeconds | default 5 }}
            failureThreshold: {{ .Values.app.livenessProbe.failureThreshold | default 3 }}
            successThreshold: {{ .Values.app.livenessProbe.successThreshold | default 1 }}
            httpGet:
              path: {{- if .Values.app.useHealth }} /actuator/health/liveness {{ else }} /api/version {{- end }}
              port: http
              scheme: {{- if .Values.app.useTLS }} HTTPS {{ else }} HTTP {{- end }}
          readinessProbe:
            initialDelaySeconds: {{ .Values.app.readinessProbe.initialDelaySeconds | default 60 }}
            periodSeconds: {{ .Values.app.readinessProbe.periodSeconds | default 5 }}
            timeoutSeconds: {{ .Values.app.readinessProbe.timeoutSeconds | default 5 }}
            failureThreshold: {{ .Values.app.readinessProbe.failureThreshold | default 3 }}
            successThreshold: {{ .Values.app.readinessProbe.successThreshold | default 1 }}
            httpGet:
              path: {{- if .Values.app.useHealth }} /actuator/health/readiness {{ else }} /api/version {{- end }}
              port: http
              scheme: {{- if .Values.app.useTLS }} HTTPS {{ else }} HTTP {{- end }}
          env:
            {{- range $key, $value := .Values.app.env_vars }}
            - name: {{ $key }}
              value: {{ $value | quote}}{{- end }}
            - name: SPRING_PROFILE
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: SPRING_PROFILE
            - name: SPRING_PROFILES_ACTIVE
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: spring.profile.active
            - name: CLUSTER_NAME
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: cluster.name
            - name: NAMESPACE_NAME
              valueFrom:
                fieldRef:
                  fieldPath: metadata.namespace
            - name: APPLICATION_NAME
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: application.name
            - name: OTLP_ENDPOINT
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: otlp.endpoint
            - name: OTLP_PROTOCOL
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: otlp.protocol
            - name: OTEL_TRACES_SAMPLER_ARG
              valueFrom:
                configMapKeyRef:
                  name: {{ include "app.fullname" . }}-config
                  key: otel.traces.sampler.arg
          args:
            - $(SPRING_PROFILE)
          volumeMounts:
            - name: data
              mountPath: /mnt/pvc
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
        {{- if .Values.watermarkSidecar.enabled }}
        - name: watermark-sidecar
          image: "{{ .Values.watermarkSidecar.image.repository }}:{{ .Values.watermarkSidecar.image.tag }}"
          imagePullPolicy: {{ .Values.watermarkSidecar.image.pullPolicy }}
          ports:
            - name: watermark
              containerPort: {{ .Values.watermarkSidecar.port }}
              protocol: TCP
          livenessProbe:
            initialDelaySeconds: {{ .Values.watermarkSidecar.initialDelaySeconds | default 30 }}
            periodSeconds: 10
            httpGet:
              path: /health
              port: watermark
          readinessProbe:
            initialDelaySeconds: {{ .Values.watermarkSidecar.initialDelaySeconds | default 30 }}
            periodSeconds: 5
            httpGet:
              path: /health
              port: watermark
          env:
            - name: WATERMARK_HOST
              value: "0.0.0.0"
            - name: WATERMARK_PORT
              value: "{{ .Values.watermarkSidecar.port }}"
            - name: WATERMARK_ALLOWED_PATH
              value: "/mnt/afs"
            - name: WATERMARK_MODEL_TYPE
              value: "{{ .Values.watermarkSidecar.modelType | default "Q" }}"
          volumeMounts:
            - name: data
              mountPath: /mnt/afs
          resources:
            {{- toYaml .Values.watermarkSidecar.resources | nindent 12 }}
        {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

